23	/**
24	 * Captures the rules for what makes two owners the same household. Kept apart from
25	 * {@link OwnerRestControllerV1} so the request handler stays focused on orchestration while the rules
26	 * for how a last name and address are canonicalized, and when two of them match, live in one place.
27	 *
28	 * <p>Two owners belong to the same household when their last names match and their addresses match,
29	 * each compared case-insensitively after collapsing runs of whitespace to a single space and
30	 * trimming, so trivial differences in spacing or letter case still count as a match.
31	 */
32	final class HouseholdNormalizer {
33	
34	    private HouseholdNormalizer() {
35	    }
36	
37	    /**
38	     * Determines whether two owners, identified by their last name and address, belong to the same
39	     * household. Both fields are compared using {@link #normalize(String)}, so the match ignores letter
40	     * case and trivial differences in whitespace.
41	     *
42	     * @param lastNameA the first owner's last name
43	     * @param addressA  the first owner's address
44	     * @param lastNameB the second owner's last name
45	     * @param addressB  the second owner's address
46	     * @return {@code true} if both owners share the same normalized last name and address
47	     */
48	    static boolean sameHousehold(String lastNameA, String addressA, String lastNameB, String addressB) {
49	        return normalize(lastNameA).equals(normalize(lastNameB))
50	            && normalize(addressA).equals(normalize(addressB));
51	    }
52	
53	    /**
54	     * Derives the stable household identifier shared by every owner that belongs to the same
55	     * household. Because it is computed purely from the {@link #normalize(String) normalized} last
56	     * name and address, two owners that {@link #sameHousehold match} always derive the same value,
57	     * so joiners can be assigned a shared identifier without coordinating through stored state.
58	     *
59	     * @param lastName the owner's last name
60	     * @param address  the owner's address
61	     * @return a stable, opaque hex identifier for the household
62	     */
63	    static String householdId(String lastName, String address) {
64	        String key = normalize(lastName) + "\n" + normalize(address);
65	        try {
66	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
67	            StringBuilder sb = new StringBuilder(32);
68	            for (int i = 0; i < 16; i++) {
69	                sb.append(String.format("%02x", digest[i]));
70	            }
71	            return sb.toString();
72	        }
73	        catch (NoSuchAlgorithmException ex) {
74	            // SHA-256 is a required algorithm on every JVM, so this cannot happen.
75	            throw new IllegalStateException("SHA-256 is not available", ex);
76	        }
77	    }
78	
79	    /**
80	     * Normalizes a value for household comparison: leading and trailing whitespace is trimmed, every
81	     * internal run of whitespace is collapsed to a single space, and the result is lower-cased so the
82	     * comparison is case-insensitive.
83	     *
84	     * @param value the raw last name or address value, or {@code null}
85	     * @return the normalized value, or the empty string when {@code value} is {@code null}
86	     */
87	    static String normalize(String value) {
88	        if (value == null) {
89	            return "";
90	        }
91	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
92	    }
93	
94	}
